<script setup>
import {ref,onMounted,onUnmounted,computed} from 'vue'
import {api} from './api.js'
import StationLink from './StationLink.vue'
const props=defineProps({token:String,language:String})
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const data=ref(null),release=ref(null),error=ref(''),busy=ref(false),password=ref(''),confirm=ref(false),checked=ref(false),reconnecting=ref(false)
let timer,stopped=false
const request=(path,options={})=>api('/api/owner/updates'+path,{token:props.token,...options,signal:AbortSignal.timeout(25000)})
const post=(path,body={})=>request(path,{method:'POST',body:JSON.stringify(body)})
const text=code=>({completed:tr('Установлено','O‘rnatildi','Installed'),waiting:tr('Ожидает готовности','Tayyor bo‘lishi kutilmoqda','Waiting for readiness'),installing:tr('Обновляется','Yangilanmoqda','Updating'),downloading:tr('Скачивается','Yuklanmoqda','Downloading'),queued:tr('В очереди','Navbatda','Queued'),failed:tr('Не установлено','O‘rnatilmadi','Not installed'),rolled_back:tr('Возвращена прежняя версия','Oldingi versiya tiklandi','Previous version restored'),needs_review:tr('Нужна проверка специалиста','Mutaxassis tekshiruvi kerak','Service review needed'),cancelled:tr('Отменено','Bekor qilindi','Cancelled'),running:tr('Обновление выполняется','Yangilanish bajarilmoqda','Update in progress')}[code]||code)
const reason=code=>({installer_not_installed:tr('Нужно один раз установить службу обновления','Yangilash xizmatini bir marta o‘rnatish kerak','One-time updater installation required'),station_offline_or_old_software:tr('Нет связи или нужна первоначальная настройка','Aloqa yo‘q yoki dastlabki sozlash kerak','Offline or initial setup required'),station_busy:tr('Ожидаем завершения сеанса','Seans tugashini kutamiz','Waiting for the session to finish'),insufficient_space:tr('Недостаточно свободного места','Bo‘sh joy yetarli emas','Not enough free space'),release_changed_or_revoked:tr('Выпуск изменён или отозван. Проверьте обновления снова.','Versiya o‘zgartirilgan yoki bekor qilingan. Qayta tekshiring.','Release changed or withdrawn. Check again.')}[code]||tr('Требуется проверка. Данные сохранены.','Tekshiruv kerak. Ma’lumotlar saqlangan.','Review required. Data is preserved.'))
function apiError(e){
 const known={update_server_unavailable_or_signature_invalid:tr('Не удалось проверить обновления. Проверьте интернет; при повторении обратитесь к специалисту.','Yangilanish tekshirilmadi. Internetni tekshiring; takrorlansa mutaxassisga murojaat qiling.','Unable to verify updates. Check internet access; contact support if this repeats.'),installer_unavailable:reason('installer_not_installed'),'Install the trusted updater on stations first':reason('installer_not_installed'),'Password confirmation failed':tr('Неверный пароль Owner','Owner paroli noto‘g‘ri','Incorrect Owner password'),'Restore wallet redundancy before updating':tr('Сначала восстановите связь и синхронизацию главного и резервного постов.','Avval asosiy va zaxira postlar aloqasi va sinxronlashini tiklang.','First restore connectivity and synchronization between primary and standby.'),'An update is already queued':tr('Обновление уже поставлено в очередь.','Yangilanish navbatga qo‘yilgan.','An update is already queued.'),'Release changed; check again':reason('release_changed_or_revoked')}
 return known[e.message]||tr('Не удалось выполнить действие. Обновите состояние и повторите.','Amal bajarilmadi. Holatni yangilab qayta urinib ko‘ring.','Unable to complete this action. Refresh the status and try again.')
}
const running=computed(()=>data.value?.queue?.status==='running')
const available=computed(()=>release.value&&data.value?.posts?.some(p=>(p.installed?.release_no||0)<release.value.manifest.release_no))
const bytes=n=>(Number(n||0)/1024**3).toFixed(2)+' GB'
async function load(){try{data.value=await request('');error.value='';reconnecting.value=false;return true}catch(e){reconnecting.value=running.value&&data.value.queue.posts.some(p=>p.post_no===data.value.primary_post&&p.status==='installing');error.value=reconnecting.value?'':apiError(e);return false}}
async function check(){busy.value=true;error.value='';try{if(await load()&&data.value?.manage_allowed){release.value=(await post('/check')).release;checked.value=true}}catch(e){error.value=apiError(e)}finally{busy.value=false}}
async function start(){busy.value=true;error.value='';try{await post('/start',{release_no:release.value.manifest.release_no,password:password.value});confirm.value=false;await load()}catch(e){error.value=apiError(e)}finally{password.value='';busy.value=false}}
async function cancel(){busy.value=true;try{await post('/cancel');await load()}catch(e){error.value=apiError(e)}finally{busy.value=false}}
async function poll(){await load();if(!stopped)timer=setTimeout(poll,10000)}
onMounted(async()=>{await check();if(!stopped)timer=setTimeout(poll,10000)})
onUnmounted(()=>{stopped=true;clearTimeout(timer)})
</script>
<template><section class="card content">
<h1>{{tr('Обновления ПО','Dastur yangilanishlari','Software updates')}}</h1>
<p>{{tr('Управление всеми постами с главного. Занятые посты дождутся завершения сеанса.','Barcha postlar asosiy postdan boshqariladi. Band postlar seans tugashini kutadi.','Manage all stations from the primary. Busy stations wait until their session ends.')}}</p>
<p v-if="error" class="message error" role="alert">{{error}}</p>
<p v-if="reconnecting" class="message" role="status">{{tr('Главный пост перезапускается. Подключаемся…','Asosiy post qayta ishga tushmoqda. Ulanmoqda…','Primary station is restarting. Reconnecting…')}}</p>
<template v-if="data?.manage_allowed===false"><p class="message">{{tr('Обновления запускаются на главном посту','Yangilanishlar asosiy postdan boshlanadi','Start updates on the primary station')}}: {{data.primary_post}}</p><StationLink v-if="data.primary_url" :href="data.primary_url+'/owner/updates'" :language="language">{{tr('Открыть главный пост','Asosiy postni ochish','Open primary station')}}</StationLink></template>
<template v-else>
<div class="actions"><button class="quiet" :disabled="busy" @click="check">{{tr('Проверить обновления','Yangilanishlarni tekshirish','Check for updates')}}</button></div>
<section v-if="available" class="card content"><h2>{{tr('Доступна версия','Yangi versiya','Available version')}} {{release.manifest.version}}</h2><p class="release-notes">{{release.manifest.notes[language]||release.manifest.notes.ru}}</p><p>{{tr('Размер загрузки','Yuklash hajmi','Download size')}}: {{bytes(release.manifest.artifact.bytes)}}</p><button class="primary" :disabled="busy||running" @click="confirm=true">{{tr('Обновить посты','Postlarni yangilash','Update stations')}}</button></section>
<p v-else-if="checked&&!running" class="message">{{tr('Новых опубликованных версий нет.','Yangi chiqarilgan versiyalar yo‘q.','No newer published release is available.')}}</p>
<div class="table-wrap"><table><thead><tr><th>{{tr('Пост','Post','Station')}}</th><th>{{tr('Версия','Versiya','Version')}}</th><th>{{tr('Состояние','Holat','Status')}}</th><th>{{tr('Свободно','Bo‘sh joy','Free space')}}</th></tr></thead><tbody><tr v-for="p in data?.posts||[]" :key="p.post_no"><th>{{p.post_no}}</th><td>{{p.installed?.version==='legacy'?tr('До подключения обновлений','Yangilash ulanishidan oldingi','Before updater setup'):p.installed?.version||'—'}}</td><td>{{!p.online?reason('station_offline_or_old_software'):(!p.ok||!p.trusted_key_configured)?reason('installer_not_installed'):p.ready?tr('Готов','Tayyor','Ready'):reason('station_busy')}}</td><td>{{p.free_bytes?bytes(p.free_bytes):'—'}}</td></tr></tbody></table></div>
<section v-if="data?.queue" class="card content"><h2>{{data.queue.version}} — {{text(data.queue.status)}}</h2><ul><li v-for="p in data.queue.posts" :key="p.post_no">{{tr('Пост','Post','Station')}} {{p.post_no}}: {{text(p.status)}}<span v-if="p.reason||p.error"> · {{reason(p.reason||p.error)}}</span></li></ul><p v-if="data.queue.error" class="message error">{{reason(data.queue.error)}}</p><button v-if="running" class="quiet" :disabled="busy" @click="cancel">{{tr('Отменить ожидающие посты','Kutayotgan postlarni bekor qilish','Cancel waiting stations')}}</button></section>
<p class="muted">{{tr('Перед установкой проверяются подпись, совместимость и свободное место. Временные пакеты удаляются после установки. Одна предыдущая версия и резервная копия хранятся 48 часов.','O‘rnatishdan oldin imzo, moslik va bo‘sh joy tekshiriladi. Vaqtinchalik paketlar o‘chiriladi. Oldingi versiya va zaxira nusxa 48 soat saqlanadi.','Signature, compatibility and free space are checked before installation. Temporary packages are removed. A previous version and backup are retained for 48 hours.')}}</p>
</template>
<div v-if="confirm" class="confirm-backdrop"><form class="card content confirm-dialog" role="dialog" aria-modal="true" @submit.prevent="start"><h2>{{tr('Обновить ПО мойки?','Yuvish dasturini yangilashmi?','Update site software?')}}</h2><p>{{tr('Посты обновятся по очереди, главный — последним. После его перезапуска страница подключится снова.','Postlar navbat bilan, asosiy post oxirida yangilanadi. U qayta ishga tushgach sahifa qayta ulanadi.','Stations update in sequence, primary last. This page reconnects after its restart.')}}</p><label>{{tr('Пароль Owner','Owner paroli','Owner password')}}<input v-model="password" type="password" autocomplete="current-password" required maxlength="256"/></label><div class="actions"><button type="button" class="quiet" :disabled="busy" @click="confirm=false;password=''">{{tr('Отмена','Bekor qilish','Cancel')}}</button><button class="primary" :disabled="busy||!password">{{tr('Начать обновление','Yangilashni boshlash','Start update')}}</button></div></form></div>
</section></template>
<style scoped>.release-notes{white-space:pre-wrap}</style>
